-- 데이터베이스 세트 374. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_sql_window_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 374, 'SQL 윈도 함수와 WITH 손연습: ROW_NUMBER·RANK·DENSE_RANK, PARTITION BY, 누적 합계, LAG, CTE', '판매 8건이 든 sales 테이블에서 윈도 함수를 직접 써 봅니다. 줄 번호와 순위(동점 처리가 다른 RANK, DENSE_RANK)를 매기고, PARTITION BY 로 지역마다 따로 계산하고, 윈도 함수 결과를 WITH 로 이름 붙여 지역별 최고 한 건을 뽑고, 누적 합계와 묶음 합계를 각 행 옆에 붙이고, LAG 로 앞 행의 값을 가져오고, WITH 로 중간 결과를 재사용합니다. 채점은 출력 파일을 같은 쿼리의 실제 결과와 비교합니다.', 'linux-db', '데이터베이스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 374);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 1, '줄 번호 매기기 (ROW_NUMBER)', '**배경** — **윈도 함수** 는 행을 하나로 합치지 않고 **각 행 옆에** 순위·누적합 같은 값을 붙여 주는 함수입니다. `함수() OVER (PARTITION BY 묶음 ORDER BY 정렬)` 형태로 쓰고, `PARTITION BY` 는 묶음별로 따로 계산하게 합니다. 이 세트의 문제는 데이터베이스 `shop`(`mariadb shop -e ''쿼리''` 로 접속해 실행)의 `sales` 테이블을 씁니다. 문제마다 처음 상태에서 다시 시작합니다.

- `sales`(판매 8건): `id`, `region`(east·west·north), `rep`(담당자), `amount`(금액), `sold_on`(판매일, 2026-01-01~03)
- 금액이 같은 행이 있습니다(west 의 `park`·`choi` 가 모두 500).

**문제** — `ROW_NUMBER()` 는 정렬 순서대로 1, 2, 3, ... 번호를 매깁니다. 모든 판매를 **금액이 큰 순서대로** (금액이 같으면 `id` 순) 번호(별칭 `rn`)를 매겨, `id`, `amount`, `rn` 세 컬럼을 `rn` 순서로 **`/tmp/q1.txt`** 에 저장하세요.', '`ROW_NUMBER() OVER (ORDER BY amount DESC, id) AS rn` 처럼 `OVER` 안에 번호를 매길 기준 정렬을 적습니다. 전체 결과의 정렬은 바깥 `ORDER BY rn` 으로 따로 정하세요.', 'mariadb shop -e ''SELECT id, amount, ROW_NUMBER() OVER (ORDER BY amount DESC, id) AS rn FROM sales ORDER BY rn;'' > /tmp/q1.txt
cat /tmp/q1.txt

# OVER (ORDER BY ...) 의 순서대로 1, 2, 3 ... 번호가 붙는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q1.txt ] && [ \\"$(cat /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, ROW_NUMBER() OVER (ORDER BY amount DESC, id) AS rn FROM sales ORDER BY rn\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q1.txt 가 금액 순 번호(1~8)와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q1.txt ] && [ \\"$(cat /tmp/q1.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, ROW_NUMBER() OVER (ORDER BY amount DESC, id) AS rn FROM sales ORDER BY rn\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 2, '같은 값은 같은 순위 (RANK)', '`RANK()` 는 값이 같으면 **같은 순위** 를 주고, 그다음 순위는 건너뜁니다. 모든 판매를 금액이 큰 순서로 순위(별칭 `rk`)를 매겨 `id`, `amount`, `rk` 를 `rk`, `id` 순서로 **`/tmp/q2.txt`** 에 저장하세요.', '`RANK() OVER (ORDER BY amount DESC) AS rk` 입니다. 금액이 같은 두 행(500)이 어떤 순위를 받고 그다음 행(400)이 몇 위가 되는지 결과로 확인하세요.', 'mariadb shop -e ''SELECT id, amount, RANK() OVER (ORDER BY amount DESC) AS rk FROM sales ORDER BY rk, id;'' > /tmp/q2.txt
cat /tmp/q2.txt

# RANK 는 동점에 같은 순위를 주고 다음 순위는 건너뛴다 (1, 1, 3, ...)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, RANK() OVER (ORDER BY amount DESC) AS rk FROM sales ORDER BY rk, id\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q2.txt 가 순위(1, 1, 3, 4, ...)와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q2.txt ] && [ \\"$(cat /tmp/q2.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, RANK() OVER (ORDER BY amount DESC) AS rk FROM sales ORDER BY rk, id\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 3, '순위를 건너뛰지 않기 (DENSE_RANK)', '`DENSE_RANK()` 는 값이 같으면 같은 순위를 주되, 그다음 순위를 **건너뛰지 않고 이어서** 매깁니다. 같은 기준으로 순위(별칭 `dr`)를 매겨 `id`, `amount`, `dr` 를 `dr`, `id` 순서로 **`/tmp/q3.txt`** 에 저장하세요.', '`RANK` 와 쓰는 방법이 같고 함수 이름만 다릅니다. 금액 400 인 행이 `RANK` 에서는 3위였지만 여기서는 몇 위인지 비교해 보세요.', 'mariadb shop -e ''SELECT id, amount, DENSE_RANK() OVER (ORDER BY amount DESC) AS dr FROM sales ORDER BY dr, id;'' > /tmp/q3.txt
cat /tmp/q3.txt

# DENSE_RANK 는 동점 뒤에도 순위를 건너뛰지 않는다 (1, 1, 2, 3, ...)', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q3.txt ] && [ \\"$(cat /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, DENSE_RANK() OVER (ORDER BY amount DESC) AS dr FROM sales ORDER BY dr, id\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q3.txt 가 건너뛰지 않는 순위(1, 1, 2, 3, ...)와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q3.txt ] && [ \\"$(cat /tmp/q3.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, DENSE_RANK() OVER (ORDER BY amount DESC) AS dr FROM sales ORDER BY dr, id\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 4, '묶음별로 따로 번호 매기기 (PARTITION BY)', '`PARTITION BY` 를 쓰면 **묶음(여기서는 지역)마다 번호가 1 부터 다시** 시작합니다. 각 지역 안에서 금액이 큰 순서(같으면 `id` 순)로 번호(별칭 `rn`)를 매겨 `region`, `id`, `amount`, `rn` 을 `region`, `rn` 순서로 **`/tmp/q4.txt`** 에 저장하세요.', '`OVER (PARTITION BY region ORDER BY amount DESC, id)` 입니다. `GROUP BY` 와 달리 행이 하나로 합쳐지지 않고 8행이 모두 남습니다.', 'mariadb shop -e ''SELECT region, id, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales ORDER BY region, rn;'' > /tmp/q4.txt
cat /tmp/q4.txt

# PARTITION BY 로 지역마다 따로 번호를 매긴다. 행은 합쳐지지 않는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q4.txt ] && [ \\"$(cat /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT region, id, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales ORDER BY region, rn\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 가 지역별 번호와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q4.txt ] && [ \\"$(cat /tmp/q4.txt)\\" = \\"$(mariadb shop -e \\"SELECT region, id, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales ORDER BY region, rn\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 5, '지역별 최고 한 건만 뽑기 (WITH + 윈도 함수)', '**배경** — 윈도 함수의 결과는 `WHERE` 에 바로 쓸 수 없습니다. 그래서 먼저 번호를 매긴 쿼리에 `WITH 이름 AS (...)` 로 **이름을 붙이고**(이를 CTE 라 부릅니다), 바깥 `SELECT` 에서 그 이름을 테이블처럼 거릅니다.

**문제** — **지역마다 금액이 가장 큰 판매 한 건** 의 `region`, `rep`, `amount` 를 `region` 순서로 **`/tmp/q5.txt`** 에 저장하세요. (금액이 같으면 `id` 가 작은 쪽)', '지역별 번호를 매긴 쿼리를 `WITH r AS (...)` 로 묶고, `SELECT ... FROM r WHERE rn = 1` 로 1번만 남기세요.', 'mariadb shop -e ''WITH r AS (SELECT region, rep, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales) SELECT region, rep, amount FROM r WHERE rn = 1 ORDER BY region;'' > /tmp/q5.txt
cat /tmp/q5.txt

# 윈도 함수 결과는 WHERE 에 못 쓰니 WITH 로 이름을 붙이고 바깥에서 rn = 1 만 거른다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q5.txt ] && [ \\"$(cat /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"WITH r AS (SELECT region, rep, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales) SELECT region, rep, amount FROM r WHERE rn = 1 ORDER BY region\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q5.txt 가 지역별 최고 판매 3건과 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q5.txt ] && [ \\"$(cat /tmp/q5.txt)\\" = \\"$(mariadb shop -e \\"WITH r AS (SELECT region, rep, amount, ROW_NUMBER() OVER (PARTITION BY region ORDER BY amount DESC, id) AS rn FROM sales) SELECT region, rep, amount FROM r WHERE rn = 1 ORDER BY region\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 6, '누적 합계 (SUM ... OVER)', '판매를 **판매일 순서(같은 날이면 `id` 순)** 로 보면서 **금액의 누적 합계**(별칭 `running`)를 각 행에 붙여 `id`, `sold_on`, `amount`, `running` 을 같은 순서로 **`/tmp/q6.txt`** 에 저장하세요.', '`SUM(amount) OVER (ORDER BY sold_on, id)` 처럼 집계 함수 뒤에 `OVER` 를 붙이면 **지금 행까지의 합** 이 됩니다.', 'mariadb shop -e ''SELECT id, sold_on, amount, SUM(amount) OVER (ORDER BY sold_on, id) AS running FROM sales ORDER BY sold_on, id;'' > /tmp/q6.txt
cat /tmp/q6.txt

# SUM(...) OVER (ORDER BY ...) 는 지금 행까지의 누적 합이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q6.txt ] && [ \\"$(cat /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, sold_on, amount, SUM(amount) OVER (ORDER BY sold_on, id) AS running FROM sales ORDER BY sold_on, id\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q6.txt 가 누적 합계와 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q6.txt ] && [ \\"$(cat /tmp/q6.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, sold_on, amount, SUM(amount) OVER (ORDER BY sold_on, id) AS running FROM sales ORDER BY sold_on, id\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 7, '각 행 옆에 묶음 합계 붙이기', '각 판매 옆에 **그 판매가 속한 지역의 금액 합계**(별칭 `region_total`)를 붙여 `id`, `region`, `amount`, `region_total` 을 `id` 순서로 **`/tmp/q7.txt`** 에 저장하세요. 행이 합쳐지면 안 됩니다(8행).', '`SUM(amount) OVER (PARTITION BY region)` 처럼 `OVER` 안에 `ORDER BY` 없이 `PARTITION BY` 만 쓰면 묶음 전체의 합이 각 행에 붙습니다.', 'mariadb shop -e ''SELECT id, region, amount, SUM(amount) OVER (PARTITION BY region) AS region_total FROM sales ORDER BY id;'' > /tmp/q7.txt
cat /tmp/q7.txt

# PARTITION BY 만 쓰면 묶음 전체의 합을 각 행 옆에 붙인다. GROUP BY 와 달리 행이 남는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q7.txt ] && [ \\"$(cat /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, region, amount, SUM(amount) OVER (PARTITION BY region) AS region_total FROM sales ORDER BY id\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q7.txt 가 지역 합계가 붙은 8행과 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q7.txt ] && [ \\"$(cat /tmp/q7.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, region, amount, SUM(amount) OVER (PARTITION BY region) AS region_total FROM sales ORDER BY id\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 8, '바로 앞 행의 값 가져오기 (LAG)', '`LAG(컬럼)` 은 정렬했을 때 **바로 앞 행의 값** 을 가져옵니다. `id` 순서로 각 판매의 **앞 판매 금액**(별칭 `prev_amount`)을 붙여 `id`, `amount`, `prev_amount` 를 **`/tmp/q8.txt`** 에 저장하세요. 첫 행은 앞이 없습니다.', '`LAG(amount) OVER (ORDER BY id)` 입니다. 앞 행이 없는 첫 행의 값은 `NULL` 로 나옵니다.', 'mariadb shop -e ''SELECT id, amount, LAG(amount) OVER (ORDER BY id) AS prev_amount FROM sales ORDER BY id;'' > /tmp/q8.txt
cat /tmp/q8.txt

# LAG 는 바로 앞 행의 값을 가져온다. 첫 행은 앞이 없어 NULL 이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q8.txt ] && [ \\"$(cat /tmp/q8.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, LAG(amount) OVER (ORDER BY id) AS prev_amount FROM sales ORDER BY id\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q8.txt 가 앞 행 금액이 붙은 8행과 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q8.txt ] && [ \\"$(cat /tmp/q8.txt)\\" = \\"$(mariadb shop -e \\"SELECT id, amount, LAG(amount) OVER (ORDER BY id) AS prev_amount FROM sales ORDER BY id\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 9, '중간 결과에 이름 붙여 두 번 쓰기 (WITH)', '지역별 금액 합계를 구하고, 그 합계가 **지역 합계들의 평균보다 큰** 지역의 `region` 과 합계(별칭 `total`)를 `region` 순서로 **`/tmp/q9.txt`** 에 저장하세요. 지역별 합계 쿼리는 **한 번만 쓰고 이름을 붙여** 재사용하세요.', '`WITH t AS (SELECT region, SUM(amount) AS total FROM sales GROUP BY region)` 로 이름을 붙이면, 아래에서 `t` 를 `FROM` 에도, 서브쿼리 안에도 쓸 수 있습니다.', 'mariadb shop -e ''WITH t AS (SELECT region, SUM(amount) AS total FROM sales GROUP BY region) SELECT region, total FROM t WHERE total > (SELECT AVG(total) FROM t) ORDER BY region;'' > /tmp/q9.txt
cat /tmp/q9.txt

# WITH 로 붙인 이름은 아래 쿼리에서 여러 번 쓸 수 있다. 평균(약 783)보다 큰 합계는 west(1100) 뿐이다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done\\nmariadb -e ''DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; USE shop;\\nCREATE TABLE sales (id INT PRIMARY KEY, region VARCHAR(10) NOT NULL, rep VARCHAR(20) NOT NULL, amount INT NOT NULL, sold_on DATE NOT NULL);\\nINSERT INTO sales VALUES (1,\\"east\\",\\"kim\\",100,\\"2026-01-01\\"),(2,\\"east\\",\\"lee\\",300,\\"2026-01-02\\"),(3,\\"east\\",\\"kim\\",200,\\"2026-01-03\\"),(4,\\"west\\",\\"park\\",500,\\"2026-01-01\\"),(5,\\"west\\",\\"choi\\",500,\\"2026-01-02\\"),(6,\\"west\\",\\"park\\",100,\\"2026-01-03\\"),(7,\\"north\\",\\"han\\",400,\\"2026-01-01\\"),(8,\\"north\\",\\"han\\",250,\\"2026-01-02\\");''; rm -f /tmp/*.txt"]', '["sh", "-c", "( [ -s /tmp/q9.txt ] && [ \\"$(cat /tmp/q9.txt)\\" = \\"$(mariadb shop -e \\"WITH t AS (SELECT region, SUM(amount) AS total FROM sales GROUP BY region) SELECT region, total FROM t WHERE total > (SELECT AVG(total) FROM t) ORDER BY region\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 가 평균보다 큰 지역(west)과 같다 (순서까지)", "cmd": ["sh", "-c", "[ -s /tmp/q9.txt ] && [ \\"$(cat /tmp/q9.txt)\\" = \\"$(mariadb shop -e \\"WITH t AS (SELECT region, SUM(amount) AS total FROM sales GROUP BY region) SELECT region, total FROM t WHERE total > (SELECT AVG(total) FROM t) ORDER BY region\\")\\" ]"]}]', '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 10, 'RANK 와 ROW_NUMBER 의 차이는?', '금액이 같은 두 행이 있을 때, `RANK()` 와 `ROW_NUMBER()` 의 결과는 어떻게 다를까요?', '같은 값을 같은 번호로 보는지 생각해 보세요.', NULL, NULL, '[]', 'choice', '["RANK 는 같은 값에 다른 순위를, ROW_NUMBER 는 같은 값에 같은 번호를 준다", "RANK 는 같은 값에 같은 순위를 주고, ROW_NUMBER 는 값이 같아도 서로 다른 번호를 준다", "둘은 완전히 같은 결과를 낸다", "RANK 는 행을 합쳐 하나로 만들고, ROW_NUMBER 는 행을 그대로 둔다"]', 1, '`ROW_NUMBER()` 는 값이 같아도 정렬 순서대로 1, 2, 3 ... 번호를 줍니다. `RANK()` 는 같은 값에 **같은 순위** 를 주고 그다음 순위를 건너뜁니다(1, 1, 3). 둘 다 행을 합치지 않고 각 행 옆에 값을 붙입니다.', NULL, NULL, NULL, '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 11, '묶음별로 따로 계산하기', '지역마다 따로 번호를 매기는 윈도 함수입니다. 빈칸을 채우세요.', '"~로 나누다"라는 뜻의 영어 두 단어 중 첫 단어예요.', NULL, NULL, '[]', 'fill', '["PARTITION", "GROUP", "SPLIT", "DIVIDE"]', NULL, '`OVER (PARTITION BY 컬럼 ORDER BY 컬럼)` 에서 `PARTITION BY` 가 묶음을 나눕니다. `GROUP BY` 는 행을 합치는 절이라 `OVER` 안에 쓰지 않고, `SPLIT`·`DIVIDE` 는 이 자리에 쓰는 키워드가 아닙니다.', '[0]', 'ROW_NUMBER() OVER ({0} BY region ORDER BY amount DESC)', NULL, '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 374, 12, '지역별 1등을 구하는 흐름', '지역마다 금액이 가장 큰 판매 한 건을 뽑는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '번호 매기기 → 이름 붙이기 → 거르기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["윈도 함수(`ROW_NUMBER() OVER (PARTITION BY ...)`)로 지역별 번호를 매긴다", "그 쿼리를 `WITH 이름 AS (...)` 로 묶어 이름을 붙인다", "바깥 `SELECT` 에서 번호가 1 인 행만 거른다", "결과가 지역마다 한 행인지 확인한다"]', NULL, '먼저 윈도 함수로 지역별 번호를 매기고, 그 쿼리에 `WITH` 로 이름을 붙인 뒤, 바깥 `SELECT` 에서 번호가 1 인 행만 남깁니다. 윈도 함수 결과는 같은 단계의 `WHERE` 에 쓸 수 없기 때문입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "MariaDB 윈도 함수", "url": "https://mariadb.com/kb/en/window-functions/"}, {"title": "MariaDB ROW_NUMBER", "url": "https://mariadb.com/kb/en/row_number/"}, {"title": "MariaDB RANK", "url": "https://mariadb.com/kb/en/rank/"}, {"title": "MariaDB DENSE_RANK", "url": "https://mariadb.com/kb/en/dense_rank/"}, {"title": "MariaDB LAG", "url": "https://mariadb.com/kb/en/lag/"}, {"title": "MariaDB WITH (CTE)", "url": "https://mariadb.com/kb/en/with/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 374 AND order_index = 12);

